import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { environment } from '../../../../environments/environment';
declare var bootstrap: any;

@Component({
  selector: 'app-detailed-user-info',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './detailed-user-info.component.html',
  styleUrls: ['./detailed-user-info.component.scss']
})
export class DetailedUserInfoComponent implements OnInit {
  user: any = null;
  loading = true;
  error: string | null = null;
  private userIdToDelete: number | null = null;
  toastMessage: string = '';
  toastType: 'success' | 'danger' | 'warning' = 'success';

  @ViewChild('toastElement') toastElement!: ElementRef;

  constructor(
    private http: HttpClient,
    private route: ActivatedRoute
  ) { }

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      const userId = params['id'];
      if (userId) {
        this.fetchUser(userId);
      }
    });
  }

  fetchUser(id: string | number) {
    this.loading = true;
    this.http.get<any>(`${environment.apiUrl}/admin/users/?id=${id}`).subscribe({
      next: (res) => {
        // Handle array or object response
        if (Array.isArray(res.data?.data)) {
          this.user = res.data.data[0] || null;
        } else {
          this.user = res.data?.data || null;
        }
        this.loading = false;
      },
      error: (err) => {
        this.error = 'Failed to load user';
        this.loading = false;
        console.error(err);
      }
    });
  }

  openDeleteModal(userId: number) {
    this.userIdToDelete = userId;
    const modalEl = document.getElementById('confirmDeleteModal');
    if (modalEl) {
      const modal = new bootstrap.Modal(modalEl);
      modal.show();
    }
  }

  confirmDelete() {
    if (!this.userIdToDelete) return;

    const token = localStorage.getItem('authToken') || '';
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });

    const body = {
      isActive: false,
      account: { id: this.userIdToDelete }
    };

    this.http.patch(`${environment.apiUrl}/admin/user`, body, { headers })
      .subscribe({
        next: () => {
          this.showToast('User Account Deactivated successfully', 'success');
          if (this.user?.id === this.userIdToDelete) {
          this.fetchUser(this.user.id);
          }
        },
        error: (err) => {
          console.error(err);
          this.showToast('Error Deactivating account', 'danger');
        }
      });

    const modalEl = document.getElementById('confirmDeleteModal');
    if (modalEl) {
      const modal = bootstrap.Modal.getInstance(modalEl);
      modal?.hide();
    }

    this.userIdToDelete = null;
  }

  approveUser(user: any) {
    const token = localStorage.getItem('authToken') || '';
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });

    const body = {
      users: [{ id: user.id }],
      status: 'approved'
    };

    this.http.put(`${environment.apiUrl}/admin/users`, body, { headers })
      .subscribe({
        next: () => {
          this.showToast(`User ${user.doptOfficer?.englishName} approved successfully`, 'success');
          this.fetchUser(user.id);
        },
        error: (err) => {
          console.error(err);
          this.showToast('Failed to approve user', 'danger');
        }
      });
  }

  rejectUser(user: any) {
    const token = localStorage.getItem('authToken') || '';
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });

    const body = {
      users: [{ id: user.id }],
      status: 'created'
    };

    this.http.put(`${environment.apiUrl}/admin/users`, body, { headers })
      .subscribe({
        next: () => {
          this.showToast(`User ${user.doptOfficer?.englishName} moved to pending list`, 'warning');
          this.fetchUser(user.id);
        },
        error: (err) => {
          console.error(err);
          this.showToast('Failed to move user', 'danger');
        }
      });
  }

  showToast(message: string, type: 'success' | 'danger' | 'warning') {
    this.toastMessage = message;
    this.toastType = type;
    const toastBootstrap = new bootstrap.Toast(this.toastElement.nativeElement);
    toastBootstrap.show();
  }
}
